12	// rewriteTopLevelField 读取 path 处的状态文件，按 mutate 改写顶层字段后写回，
13	// 返回改写前的字节。数字以 json.Number 保留词面写法，使指数形式、超界整数
14	// 等非法写法能逐字落盘，不被 float64 折叠。
15	func rewriteTopLevelField(t *testing.T, path string, mutate func(doc map[string]any)) []byte {
16		t.Helper()
17		good, err := os.ReadFile(path)
18		if err != nil {
19			t.Fatal(err)
20		}
21		dec := json.NewDecoder(bytes.NewReader(good))
22		dec.UseNumber()
23		var doc map[string]any
24		if err := dec.Decode(&doc); err != nil {
25			t.Fatal(err)
26		}
27		mutate(doc)
28		bad, err := json.MarshalIndent(doc, "", "  ")
29		if err != nil {
30			t.Fatal(err)
31		}
32		bad = append(bad, '\n')
33		if err := os.WriteFile(path, bad, 0o600); err != nil {
34			t.Fatal(err)
35		}
36		return good
37	}
