39	// TestTreasuryFieldsRequired：顶层的 initial_treasury 与 treasury 都必须明确
40	// 写出且为 int64 范围内的 JSON 整数。字段缺失、为 null、写成字符串/布尔/
41	// 小数/指数形式或超出范围，都判整份状态文件损坏，错误指出具体是哪一个
42	// 字段；金额为负的既有拒绝保持不变。资金记录是否完整独立判断：即使初始
43	// 金额为零、尚无执行凭据、其余记录恰好能与零核对一致，缺失字段也不得被
44	// 折叠成 0 再认可；明确写出的两个 0 仍是合法资金库。
45	func TestTreasuryFieldsRequired(t *testing.T) {
46		mutations := map[string]struct {
47			mutate func(doc map[string]any)
48			want   string
49		}{
50			"initial missing": {
51				mutate: func(doc map[string]any) { delete(doc, "initial_treasury") },
52				want:   `field "initial_treasury" is missing`,
53			},
54			"treasury missing": {
55				mutate: func(doc map[string]any) { delete(doc, "treasury") },
56				want:   `field "treasury" is missing`,
57			},
58			"initial null": {
59				mutate: func(doc map[string]any) { doc["initial_treasury"] = nil },
60				want:   `field "initial_treasury" is null`,
61			},
62			"treasury null": {
63				mutate: func(doc map[string]any) { doc["treasury"] = nil },
64				want:   `field "treasury" is null`,
65			},
66			"initial string": {
67				mutate: func(doc map[string]any) { doc["initial_treasury"] = "0" },
68				want:   `field "initial_treasury" has wrong type: want integer, got string`,
69			},
70			"treasury string": {
71				mutate: func(doc map[string]any) { doc["treasury"] = "0" },
72				want:   `field "treasury" has wrong type: want integer, got string`,
73			},
74			"initial boolean": {
75				mutate: func(doc map[string]any) { doc["initial_treasury"] = false },
76				want:   `field "initial_treasury" has wrong type: want integer, got boolean`,
77			},
78			"treasury boolean": {
79				mutate: func(doc map[string]any) { doc["treasury"] = true },
80				want:   `field "treasury" has wrong type: want integer, got boolean`,
81			},
82			"initial fraction": {
83				mutate: func(doc map[string]any) { doc["initial_treasury"] = json.Number("0.5") },
84				want:   `field "initial_treasury" has wrong type: want integer, got number`,
85			},
86			"treasury fraction": {
87				mutate: func(doc map[string]any) { doc["treasury"] = json.Number("1.5") },
88				want:   `field "treasury" has wrong type: want integer, got number`,
89			},
90			"initial exponent": {
91				mutate: func(doc map[string]any) { doc["initial_treasury"] = json.Number("1e2") },
92				want:   `field "initial_treasury" has wrong type: want integer, got number`,
93			},
94			"treasury exponent": {
95				mutate: func(doc map[string]any) { doc["treasury"] = json.Number("1e2") },
96				want:   `field "treasury" has wrong type: want integer, got number`,
97			},
98			"initial out of range": {
99				mutate: func(doc map[string]any) { doc["initial_treasury"] = json.Number("9223372036854775808") },
100				want:   `field "initial_treasury" has wrong type: want integer, got number`,
101			},
102			"treasury out of range": {
103				mutate: func(doc map[string]any) { doc["treasury"] = json.Number("-9223372036854775809") },
104				want:   `field "treasury" has wrong type: want integer, got number`,
105			},
106			"initial negative": {
107				mutate: func(doc map[string]any) { doc["initial_treasury"] = json.Number("-1") },
108				want:   `initial treasury balance is negative`,
109			},
110			"treasury negative": {
111				mutate: func(doc map[string]any) { doc["treasury"] = json.Number("-1") },
112				want:   `treasury balance is negative`,
113			},
114		}
115		for name, tc := range mutations {
116			t.Run(name, func(t *testing.T) {
117				// 初始金额为零且尚无执行凭据：缺损字段恰好能与零核对一致，
118				// 也必须判损坏，不能凭计算结果相等认可缺损文件。
119				store, path := openTempStore(t, 0)
120				store.Close()
121				good := rewriteTopLevelField(t, path, tc.mutate)
122	
123				if _, err := Open(path); !errors.Is(err, ErrStateCorrupt) {
124					t.Fatalf("Open err=%v, want ErrStateCorrupt", err)
125				} else if !strings.Contains(err.Error(), tc.want) {
126					t.Fatalf("Open err=%q, want substring %q", err, tc.want)
127				}
128				// 损坏文件保持原样，不被重建或覆盖。
129				after, err := os.ReadFile(path)
130				if err != nil {
131					t.Fatal(err)
132				}
133				if string(after) == string(good) {
134					t.Fatalf("corrupt file was overwritten")
135				}
136			})
137		}
138	}
